def solve(a):
    a=np.array(a); h,w=a.shape
    from collections import Counter
    bg=Counter(a.flatten()).most_common(1)[0][0]
    colors=[c for c in np.unique(a) if c!=bg]
    def solid(c):
        ys,xs=np.where(a==c); rs,cx=ys.min(),xs.min(); return (ys.max()-rs+1)*(xs.max()-cx+1)==len(ys)
    anc=[c for c in colors if solid(c)][0]
    ys_,xs_=np.where(a==anc); cy=(ys_.min()+ys_.max())/2; cx=(xs_.min()+xs_.max())/2
    out=a.copy()
    for c in colors:
        if c==anc: continue
        ys,xs=np.where(a==c)
        for y,x in zip(ys,xs):
            for ny,nx in ((round(2*cy-y), x), (y, round(2*cx-x)), (round(2*cy-y), round(2*cx-x))):
                if 0<=ny<h and 0<=nx<w and a[ny,nx]==bg: out[ny,nx]=c
    return out.tolist()
print(solve(G['Demo pair 1 input'])==G['Demo pair 1 output'])
print(json.dumps(solve(G['Test input'])))
